import pyomo.environ as pyo

DATA = {
    "n": 4,
    "cost": {
        (0, 1): 616, (0, 2): 567, (0, 3): 143,
        (1, 0): 388, (1, 2): 947, (1, 3): 628,
        (2, 0): 495, (2, 1): 650, (2, 3): 604,
        (3, 0): 77,  (3, 1): 630, (3, 2): 23,
    },
    "big_m": 4,          # > n, valid for MTZ
    "pos_lb": 0,
    "pos_ub": 3,
    "city0_pos": 0,      # position of City 0 fixed
    "obj_pos_coef_city0": 0,  # the stated 0 * position[City 0] term
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    n = d["n"]
    cost = d["cost"]
    M = d["big_m"]

    model = pyo.ConcreteModel()

    # --- Sets ---
    model.N = pyo.RangeSet(0, n - 1)
    model.A = pyo.Set(
        dimen=2,
        initialize=[(i, j) for i in range(n) for j in range(n) if i != j],
    )

    # --- Variables ---
    model.x = pyo.Var(model.A, domain=pyo.Binary)

    def u_bounds(m, i):
        if i == 0:
            return (d["city0_pos"], d["city0_pos"])
        return (d["pos_lb"], d["pos_ub"])

    model.u = pyo.Var(model.N, domain=pyo.Integers, bounds=u_bounds)

    # --- Objective: minimize total cost (incl. 0 * u[0] term) ---
    def obj_rule(m):
        return (
            sum(cost[(i, j)] * m.x[i, j] for (i, j) in m.A)
            + d["obj_pos_coef_city0"] * m.u[0]
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Degree constraints: exactly one departure per city ---
    def out_rule(m, i):
        return sum(m.x[i, j] for j in range(n) if (i, j) in m.A) == 1

    model.out_degree = pyo.Constraint(model.N, rule=out_rule)

    # --- Degree constraints: exactly one arrival per city ---
    def in_rule(m, j):
        return sum(m.x[i, j] for i in range(n) if (i, j) in m.A) == 1

    model.in_degree = pyo.Constraint(model.N, rule=in_rule)

    # --- MTZ subtour elimination ---
    # u_j >= u_i + 1 - M(1 - x_ij)  for arcs NOT leaving City 0
    def mtz_rule(m, i, j):
        if i == 0:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - M * (1 - m.x[i, j])

    model.mtz = pyo.Constraint(model.A, rule=mtz_rule)

    return model
